import { NextRequest, NextResponse } from 'next/server';
import crypto from 'node:crypto';
import { prisma } from '@/lib/db';
import { z } from 'zod';

const joinByPasscodeSchema = z.object({
  passcode: z.string().trim().min(1, 'Passcode is required'),
  displayName: z.string().trim().max(50).optional(),
});

/**
 * POST /api/events/join-by-passcode
 * Join an event directly by entering a human-friendly passcode generated by the owner.
 * Sets the guest_token session cookie and returns event details for redirection.
 */
export async function POST(req: NextRequest) {
  try {
    const body = await req.json().catch(() => ({}));
    const parsed = joinByPasscodeSchema.safeParse(body);

    if (!parsed.success) {
      return NextResponse.json(
        { error: 'Please enter a valid passcode' },
        { status: 400 }
      );
    }

    const rawPasscode = parsed.data.passcode.trim();
    const displayName = parsed.data.displayName?.trim() || 'Guest Attendee';

    // Search for an active share link matching the passcode case-insensitively
    const shareLink = await prisma.shareLink.findFirst({
      where: {
        OR: [
          { token: rawPasscode },
          { token: rawPasscode.toUpperCase() },
          { token: rawPasscode.toLowerCase() },
        ],
        isRevoked: false,
        AND: [
          {
            OR: [{ expiresAt: null }, { expiresAt: { gt: new Date() } }],
          },
        ],
      },
      include: {
        event: {
          select: {
            id: true,
            name: true,
            isDeleted: true,
          },
        },
      },
    });

    if (!shareLink || !shareLink.event || shareLink.event.isDeleted) {
      return NextResponse.json(
        { error: 'Invalid or expired passcode. Please check the code with the event owner.' },
        { status: 404 }
      );
    }

    // Generate a secure temporary token for the guest session
    const temporaryToken = crypto.randomBytes(24).toString('hex');
    const expiresAt = shareLink.expiresAt || new Date(Date.now() + 14 * 24 * 60 * 60 * 1000); // 14 days default

    const guest = await prisma.guestIdentity.create({
      data: {
        eventId: shareLink.eventId,
        temporaryToken,
        displayName,
        expiresAt,
      },
    });

    const response = NextResponse.json({
      success: true,
      eventId: shareLink.eventId,
      eventName: shareLink.event.name,
      displayName: guest.displayName,
      canUpload: shareLink.canUpload,
      canView: shareLink.canView,
    });

    // Set secure HTTP-only cookie for this event
    response.cookies.set(`guest_token_${shareLink.eventId}`, temporaryToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      path: '/',
      maxAge: 14 * 24 * 60 * 60, // 14 days
    });

    return response;
  } catch (err: unknown) {
    console.error('[API join-by-passcode error]:', err);
    return NextResponse.json(
      { error: (err as Error).message || 'Failed to join with passcode' },
      { status: 500 }
    );
  }
}
